schemaPerTenant.snippet:
// Resolver schema por tenant
const client = await pool.connect();
await client.query(`SET search_path TO tenant_${tenantId}, public`);

const { rows } = await client.query(
  'SELECT * FROM invoices LIMIT 50'
);

dbPerTenant.snippet:
// Router de conexión por tenant
const dsn = await vault.getTenantDsn(tenantId);
const db = getOrCreatePool(dsn);

return db.query(
  'SELECT * FROM invoices WHERE deleted_at IS NULL'
);
